import numpy as np

def random_search(fitness_func, dim, bounds, num_samples=200):
    """
    Random Search - Stochastic optimization
    
    Parameters:
        fitness_func: Function to minimize
        dim: Problem dimension
        bounds: Tuple (lower, upper)
        num_samples: Number of random samples
    
    Returns:
        best_x, best_value
    """
    lower, upper = bounds
    samples = np.random.uniform(lower, upper, (num_samples, dim))
    values = np.array([fitness_func(s) for s in samples])
    best_idx = np.argmin(values)
    return samples[best_idx], values[best_idx]


def brute_force(fitness_func, x_range, resolution=1000):
    """
    Brute Force Search - Deterministic grid search
    
    Parameters:
        fitness_func: Function to minimize
        x_range: Tuple (min, max) for search range
        resolution: Number of points to evaluate
    
    Returns:
        best_x, best_value
    """
    x_values = np.linspace(x_range[0], x_range[1], resolution)
    y_values = np.array([fitness_func(x) for x in x_values])
    best_idx = np.argmin(y_values)
    return x_values[best_idx], y_values[best_idx]
